#!/usr/bin/env node
import { execFileSync } from 'node:child_process';
import { readFileSync } from 'node:fs';
import { pathToFileURL } from 'node:url';

export function inventory(query, { env = process.env, execute = execFileSync } = {}) {
  const { roles, expected_account_id: account, region } = query;
  if (!/^[0-9]{12}$/.test(account) || account === '000000000000' || !/^[a-z]{2}-[a-z]+-\d$/.test(region)
    || ['AWS_ENDPOINT_URL', 'AWS_ENDPOINT_URL_IAM', 'AWS_ENDPOINT_URL_STS'].some(k => env[k] !== undefined)) throw new Error('live account and unmodified AWS endpoints required');
  const names = roles?.split(',');
  if (!names?.length || new Set(names).size !== names.length || names.some(n => !/^crpko-(dev|staging|prod)-gha-readiness$/.test(n))) throw new Error('exact owned readiness role set required');
  const aws = (service, action, args = []) => JSON.parse(execute('aws', [service, action, ...args, '--region', region, '--output', 'json'], {
    env, encoding: 'utf8', timeout: 60000, maxBuffer: 8 * 1024 * 1024, stdio: ['pipe', 'pipe', 'pipe']
  }));
  if (aws('sts', 'get-caller-identity').Account !== account) throw new Error('inventory account mismatch');
  return Object.fromEntries(names.sort().map(name => {
    let role;
    try { role = aws('iam', 'get-role', ['--role-name', name]).Role; }
    catch (error) {
      if (/\(NoSuchEntity\) when calling the GetRole operation/.test(String(error.stderr))) return [name, JSON.stringify({ exists: false, inline: [], attached: [] })];
      throw new Error(`inventory GetRole failed for ${name}`, { cause: error });
    }
    if (role?.RoleName !== name || role.Arn !== `arn:aws:iam::${account}:role/${name}`) throw new Error('inventory role identity mismatch');
    const inline = aws('iam', 'list-role-policies', ['--role-name', name]).PolicyNames;
    const attached = aws('iam', 'list-attached-role-policies', ['--role-name', name]).AttachedPolicies;
    if (!Array.isArray(inline) || inline.some(x => typeof x !== 'string') || !Array.isArray(attached) || attached.some(x => typeof x.PolicyArn !== 'string')) throw new Error('inventory policy lists incomplete');
    return [name, JSON.stringify({ exists: true, inline: inline.sort(), attached: attached.map(p => p.PolicyArn).sort() })];
  }));
}
if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  try { process.stdout.write(`${JSON.stringify(inventory(JSON.parse(readFileSync(0, 'utf8'))))}\n`); }
  catch { process.stderr.write('gha-env-roles inventory could not be proven\n'); process.exitCode = 1; }
}
